const LENSES = [
  { key: 'spec-text', brief: 'Lens: the SPEC, CLARIFICATIONS, TASK, DESIGN and CHARTER TEXT. Re-read the exact passages and decide whether they say what the finding claims. A finding that attributes to them something they do not say, or treats as a defect what they explicitly permit, is refuted.' },
