        properties: {
          id: { type: 'string' },
          status: { type: 'string', enum: ['confirmed', 'refuted', 'unverified'] },
          evidence: { type: 'string', description: 'what you checked and the output' },
          fix: { type: 'string', description: 'smallest correct fix if confirmed' },
