]

const results = await pipeline(
  FINDERS,
  f => agent(`You are an adversarial, read-only reviewer of a Lean 4 formalization pass.\n${CONTEXT}\n${f.prompt}\n\nReturn only findings you can back with evidence (spec/brief quote, counterexample, or command output you actually ran). Do not request additions beyond the task. Return an empty list if nothing survives your own scrutiny.`,
    { label: `find:${f.key}`, phase: 'Find', schema: FINDINGS }),
  (r, f) => {
    const fs = (r && r.findings) || []
    if (!fs.length) return { key: f.key, findings: [], verdicts: [] }
    return agent(`You are a skeptical judge. Your job is to REFUTE each finding below if you can; default to "refuted" when the evidence does not hold up, and "unverified" only if you could not check it. Re-run every command or Lean snippet the finding relies on; read the cited spec/brief text yourself.\n${CONTEXT}\nA finding is confirmed only if (a) its evidence holds when you re-check it and (b) it is within the task scope of the brief (findings that ask for additions beyond the brief are refuted). For each confirmed finding give the smallest correct fix.\n\nFindings (lens: ${f.key}):\n${JSON.stringify(fs, null, 2)}`,
      { label: `verify:${f.key}`, phase: 'Verify', schema: VERDICTS })
      .then(v => ({ key: f.key, findings: fs, verdicts: (v && v.verdicts) || [] }))
  },
)

return results.filter(Boolean)

