SP=/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad && git show 1c1b90e:formal/Ern/MM02.lean > $SP/mm02_p3.lean && cp formal/Ern/MM02.lean $SP/mm02_p4.lean && python3 -I - "$SP" <<'EOF'
import re,sys
SP=sys.argv[1]
KW=re.compile(r'^(theorem|def|inductive|structure|example|instance|attribute|#eval|#guard_msgs)\b')
def decls(path):
    lines=open(path,encoding='utf-8').read().split('\n')
    out=[];cur=None;doc=None;ex=0;ns=''
    i=0
    for l in lines:
        if l.startswith('namespace Witness'): ns='Witness.'
        if l.startswith('end Witness'): ns=''
        if l.startswith('/--'): 
            if cur: out.append(cur);cur=None
            doc=l
            continue
        m=KW.match(l)
        if m:
            if cur: out.append(cur)
            k=m.group(1)
            if k in('theorem','def','inductive','structure'):
                name=ns+l.split()[1]
            elif k=='example':
                ex+=1;name=ns+'example#%d %s'%(ex,(doc or '')[4:60])
            else:
                name=ns+l.strip()[:50]
            cur=[k,name,[l]]
            continue
        if cur is not None:
            if l.strip()=='' or l.startswith('end ') or l.startswith('namespace') or l.startswith('/-!'):
                out.append(cur);cur=None
            else: cur[2].append(l)
    if cur: out.append(cur)
    return out
def stmt(k,body):
    s='\n'.join(body)
    if k in ('theorem','example'):
        # statement up to the last ':=' that starts the proof
        j=s.find(':= by')
        if j<0:
            j=s.find(':=\n')
        if j<0: j=s.rfind(':=')
        return s[:j].rstrip()
    return s
a={n:(k,stmt(k,b)) for k,n,b in decls(SP+'/mm02_p3.lean')}
b={n:(k,stmt(k,bb)) for k,n,bb in decls(SP+'/mm02_p4.lean')}
removed=[n for n in a if n not in b]
added=[n for n in b if n not in a]
changed=[n for n in a if n in b and ' '.join(a[n][1].split())!=' '.join(b[n][1].split())]
print('REMOVED',removed);print('ADDED',added);print('CHANGED',len(changed))
with open(SP+'/p4_diffdecls.txt','w',encoding='utf-8') as f:
    for n in changed:
        f.write('=== '+n+'\n--- old\n'+a[n][1]+'\n+++ new\n'+b[n][1]+'\n\n')
    for n in removed: f.write('=== REMOVED '+n+'\n'+a[n][1]+'\n\n')
    for n in added: f.write('=== ADDED '+n+'\n'+b[n][1]+'\n\n')
for n in changed: print(' ',n)
EOF

