export const meta = {
  name: 'mm03-adversarial-review',
  description: 'Adversarial review of MM03.lean and MM03_v0.1.md against MM-03.3 v0.2 and the task brief',
  phases: [{ title: 'Find' }, { title: 'Judge' }],
}
const SP = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'
const CTX = `Context (read-only review; do NOT edit any file, do NOT commit):
- Repo: /Users/guygouri/Devlab/ernlang/ern, branch formal/access_model_0.1. Lean project in formal/ (Lean 4.35, core only). Build: cd formal && ~/.elan/bin/lake build. Run scratch Lean files with: cd formal && ~/.elan/bin/lake env lean <file> (write scratch files ONLY under ${SP}/review/).
- Module under review: formal/Ern/MM03.lean (namespace Ern.MM03). Report under review: formal/reports/MM03_v0.1.md.
- Normative spec: /Users/guygouri/Downloads/ERN_Memory_Model_0.3.3.md (MM-03.3 v0.2). Also MM-03.1/MM-03.2 sections of /Users/guygouri/Downloads/ERN_Memory_model.md.
- Task brief (its "Arbitrages" are binding and override the spec where they speak): ${SP}/task_mm03.md
- formal/DESIGN.md governs how to formalize.
Rules from AGENTS.md: a definition must say exactly what its rule says (not stronger, not weaker); no unjustified hypotheses; no silent interpretation where the spec is unclear (it must be listed in report section (c) or (e)); every finding needs evidence (spec quote, counterexample, or command output). No evidence, no finding. Do not ask for additions beyond the task.`
const FIND_SCHEMA = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: {
  title: { type: 'string' }, severity: { type: 'string', enum: ['blocking', 'major', 'minor'] },
  location: { type: 'string' }, cause: { type: 'string', enum: ['formalization error', 'missing coverage', 'spec defect', 'report error'] },
  evidence: { type: 'string' }, fix: { type: 'string' } }, required: ['title', 'severity', 'location', 'cause', 'evidence'] } } }, required: ['findings'] }
const VERDICT_SCHEMA = { type: 'object', properties: { verdicts: { type: 'array', items: { type: 'object', properties: {
  title: { type: 'string' }, confirmed: { type: 'boolean' }, reason: { type: 'string' }, severity: { type: 'string' } }, required: ['title', 'confirmed', 'reason'] } } }, required: ['verdicts'] }
const LENSES = [
  { key: 'spec', prompt: `Lens: SPEC FIDELITY. For each operation (derive, split, release, transfer, depend, enterFrame, exitFrame, canRead3/read3, canWrite3/write3, arena issue/reset) and each invariant (I1-I4), effective (MM-03.3.5), compare the Lean precondition/effect clause by clause with the spec text and the binding arbitrages. Report any clause that is stronger or weaker than the text, any spec clause silently dropped or reinterpreted WITHOUT being listed in report (b)/(c)/(e), and any precondition invented without a listed justification. Quote the spec sentence and the Lean definition for each finding.` },
  { key: 'lean', prompt: `Lens: LEAN SOUNDNESS AND VACUITY. Check that theorems are not vacuous or trivially true because a definition is too permissive or hypotheses are unsatisfiable; that statement hypotheses (WF3, DDSound, ArenaResetContract, ArenaInv) are satisfiable and reasonable; that the 17 test-case examples really test what they claim (e.g. the decide target is the intended precondition, states are built as described). Run the build and an axiom sweep (#print axioms for every theorem; allowed: propext, Quot.sound only). Try to construct counterexamples by writing scratch Lean files under ${SP}/review/ with decide. Check that docstrings of definitions/theorems encoding spec rules cite the clause.` },
  { key: 'report', prompt: `Lens: REPORT ACCURACY. Check every factual claim in formal/reports/MM03_v0.1.md against the module and the spec: declaration names exist and match the description; hypotheses listed in (h) match the actual theorem statements; the (g) table matches the examples in the module (verdicts, operations used, classification); counts (theorems, axioms) are right; quoted spec sentences are verbatim; claims in (d)/(e) are backed by a Lean declaration or are correctly marked. Also check the required sections (a)-(h) are complete per the task brief.` },
  { key: 'arbitrage', prompt: `Lens: ARBITRAGE AND TASK COMPLIANCE. Check each of the 6 binding arbitrages in the task brief and each step requirement: e.g. arbitrage 1 (re-anchoring at exitFrame on the origin if it lives in a surviving frame, else reject), arbitrage 2 (anchors are authorities, each place has a root authority), arbitrage 3 (arena: footprint covers only metadata, internal authority separate root, issue derives blocks from it and anchors them on the arena, reset governed by I3 never I1; Vec elements are parts), arbitrage 4, arbitrage 5 (theorems conditioned on K hypotheses named and documented as such), arbitrage 6 (reject vs defined failure vs ub). Check git history: one commit per step, French messages, nothing outside formal/, MM02.lean unmodified (git diff formal/memory_model_0.3 -- formal/Ern/MM02.lean). Report deviations with evidence.` },
]
const results = await pipeline(LENSES,
  l => agent(`${CTX}\n\n${l.prompt}\n\nReturn findings (possibly empty). Be adversarial but only report what you can evidence.`, { label: `find:${l.key}`, phase: 'Find', schema: FIND_SCHEMA }),
  (r, l) => (r && r.findings && r.findings.length) ? agent(`${CTX}\n\nYou are a skeptical judge. For EACH finding below, try to REFUTE it by reading the module, report, spec and brief, and running Lean if useful. Confirm only if the evidence holds and the issue is real and within the task's scope. Default to refuted if the evidence does not hold. Adjust severity if warranted.\n\nFindings (lens ${l.key}):\n${JSON.stringify(r.findings, null, 1)}`, { label: `judge:${l.key}`, phase: 'Judge', schema: VERDICT_SCHEMA }).then(v => ({ lens: l.key, findings: r.findings, verdicts: v ? v.verdicts : [] })) : { lens: l.key, findings: [], verdicts: [] }
)
return results

